    public static double CalculateExpression(string expr)
    {
        int pos = 1;
        while (expr[pos] != '+' && expr[pos] != '-' && expr[pos] != '*' && expr[pos] != '/')
            pos++;
        double a = double.Parse(expr.Substring(0, pos));
        double b = double.Parse(expr.Substring(pos + 1));
        char op = expr[pos];
        if (op == '+')
            return a + b;
        else if (op == '-')
            return a - b;
        else if (op == '*')
            return a * b;
        else
            return a / b;
    }

    public static void Main()
    {
        string expr = Console.ReadLine();
        Console.WriteLine(CalculateExpression(expr));
    }
