    public int FindSeller(int minRate, int maxRate)
    {
        for (int i = 0; i < allSellers.Length; i++)
        {
            Seller s = allSellers[i];
            if (s != null && s.GetIsTopSeller() && s.GetRate() > minRate && s.GetRate() < maxRate)
                return i;
        }
        return -1;
    }

    public int[] SellersGroup()
    {
        int[] groups = new int[3];
        for (int i = 0; i < allSellers.Length; i++)
        {
            if (allSellers[i] != null)
            {
                double r = allSellers[i].GetRate();
                if (r < 3)
                    groups[0]++;
                else if (r < 4)
                    groups[1]++;
                else
                    groups[2]++;
            }
        }
        return groups;
    }
}

