public class Test
{
    private int sugarLevel;
    private int pulse;
    private int oxygenSaturation;

    public Test(int sugarLevel, int pulse, int oxygenSaturation)
    {
        this.sugarLevel = sugarLevel;
        this.pulse = pulse;
        this.oxygenSaturation = oxygenSaturation;
    }

    public bool IsNormal()
    {
        return sugarLevel >= 70 && sugarLevel <= 100 && pulse >= 60 && pulse <= 90 && oxygenSaturation >= 97;
    }

    public bool IsLifeThreatening()
    {
        return sugarLevel < 50 || pulse < 40 || pulse > 120 || oxygenSaturation < 93;
    }
}

public class Patient
{
    private string name;
    private Test[] tests;

    public Patient(string name, Test[] tests)
    {
        this.name = name;
        this.tests = tests;
    }

    public void PrintLongestNormal()
    {
        int max = 0, current = 0;
        for (int i = 0; i < tests.Length; i++)
        {
            if (tests[i].IsNormal())
            {
                current++;
                if (current > max)
                    max = current;
            }
            else
                current = 0;
        }
        Console.WriteLine(max);
    }

    public bool HasLifeThreat()
    {
        for (int i = 0; i < tests.Length; i++)
            if (tests[i].IsLifeThreatening())
                return true;
        return false;
    }
}

public class Program
{
    public static void Main()
    {
        string name = Console.ReadLine();
        int n = int.Parse(Console.ReadLine());
