public class ThinkAndDrink
{
    const int MONTH = 12, DAY = 31;
    private Lecture[,] mat;

    public ThinkAndDrink()
    {
        mat = new Lecture[MONTH, DAY];
    }

    public Lecture GetLecture(int day, int month) { return mat[month - 1, day - 1]; }

    public bool AddLecture(int day, int month, Lecture lec)
    {
        int m = month - 1, d = day - 1;
        for (int dist = 0; dist < DAY; dist++)
        {
            if (d - dist >= 0 && mat[m, d - dist] == null)
            {
                mat[m, d - dist] = lec;
                return true;
            }
            if (d + dist < DAY && mat[m, d + dist] == null)
            {
                mat[m, d + dist] = lec;
                return true;
            }
        }
        return false;
    }
}

public class Program
{
    public static void Main()
    {
        ThinkAndDrink plan = new ThinkAndDrink();
        int n = int.Parse(Console.ReadLine());
        for (int i = 0; i < n; i++)
        {
            int day = int.Parse(Console.ReadLine());
            int month = int.Parse(Console.ReadLine());
            Lecture lec = new Lecture(Console.ReadLine(), Console.ReadLine(), Console.ReadLine(), int.Parse(Console.ReadLine()));
