using System;

public class Color
{
    private bool isBlk;
    private int[] colors;

    public Color(bool isBlk, int[] colors)
    {
        this.isBlk = isBlk;
        this.colors = new int[colors.Length];
        for (int i = 0; i < colors.Length; i++)
        {
            if (isBlk)
                this.colors[i] = 1 - colors[i];
            else
                this.colors[i] = colors[i];
        }
    }

    public int[] GetColors() { return colors; }

    public void Not(int i)
    {
        colors[i] = 1 - colors[i];
    }

    public bool Blk()
    {
        int black = 0;
        for (int i = 0; i < colors.Length; i++)
            if (colors[i] == 1)
                black++;
        return black > colors.Length - black;
    }

    public void White()
    {
        for (int i = 0; i < colors.Length; i++)
            if (colors[i] == 1)
                Not(i);
    }
}

public class Picture
{
    private string name;
    private Color color;

    public Picture(string name, Color color)
    {
        this.name = name;
        this.color = color;
    }

    public string GetName() { return name; }
    public Color GetColor() { return color; }

    public bool ChangeColor()
    {
        if (color.Blk())
        {
            int[] c = color.GetColors();
            for (int i = 0; i < c.Length; i++)
                color.Not(i);
            return true;
        }
        color.White();
        return false;
    }
}

public class Program
{
